import { useCallback, useEffect, useMemo, useState } from 'react'

import { EmptyState, ErrorState, LoadingState } from '../../components/shared/ViewState'
import { StatusBadge } from '../../components/shared/StatusBadge'
import { apiClient, type FamilyHeadDto, type PagedResult } from '../../services/apiClient'

type FilterStatus = 'ALL' | 'PENDING' | 'VERIFIED' | 'MORE_INFO' | 'REJECTED' | 'SUSPENDED'

export function FamilyHeadVerificationPage() {
  const [familyHeads, setFamilyHeads] = useState<FamilyHeadDto[]>([])
  const [status, setStatus] = useState<'loading' | 'ready' | 'error'>('loading')
  const [message, setMessage] = useState('')
  const [generatedTokenInfo, setGeneratedTokenInfo] = useState<{ email: string; token: string } | null>(null)
  const [search, setSearch] = useState('')
  const [activeFilter, setActiveFilter] = useState<FilterStatus>('ALL')

  const load = useCallback(async () => {
    setStatus('loading')
    try {
      const response = await apiClient.get<PagedResult<FamilyHeadDto>>('/admin/family-heads', {
        params: { page: 1, pageSize: 100 },
      })
      setFamilyHeads(response.data.items)
      setStatus('ready')
    } catch {
      setStatus('error')
    }
  }, [])

  useEffect(() => {
    void load()
  }, [load])

  async function handleResetPassword(userId: string, email: string) {
    try {
      const response = await apiClient.post<{ success: boolean; message: string; resetToken?: string }>(
        `/auth/admin/users/${userId}/reset-password`,
        { reason: 'Administrative password reset' }
      )
      setMessage(`Password reset token generated for ${email} and logged to audit trail.`)
      if (response.data.resetToken) {
        setGeneratedTokenInfo({ email, token: response.data.resetToken })
      }
    } catch {
      setMessage('Failed to generate password reset token.')
    }
  }

  async function decide(userId: string, action: 'verify' | 'request-info' | 'reject' | 'suspend') {
    const actionLabels: Record<string, string> = {
      verify: 'Administrative verification completed',
      'request-info': 'Additional identity documents requested',
      reject: 'Registration rejected by administrator',
      suspend: 'Account suspended by administrator',
    }
    try {
      const response = await apiClient.post<FamilyHeadDto>(`/admin/family-heads/${userId}/${action}`, {
        reason: actionLabels[action] ?? 'Administrative verification update',
      })
      const codeMsg = response.data.familyCode ? ` Assigned Family ID: ${response.data.familyCode}` : ''
      setMessage(`Family head verification status updated and audited.${codeMsg}`)
      await load()
    } catch {
      setMessage('Verification status could not be updated.')
    }
  }

  const filteredHeads = useMemo(() => {
    return familyHeads.filter((head) => {
      const q = search.toLowerCase().trim()
      const matchesSearch =
        q === '' ||
        head.displayName.toLowerCase().includes(q) ||
        head.email.toLowerCase().includes(q) ||
        head.familyName.toLowerCase().includes(q) ||
        (head.familyCode && head.familyCode.toLowerCase().includes(q)) ||
        (head.nic && head.nic.toLowerCase().includes(q)) ||
        (head.address && head.address.toLowerCase().includes(q))

      if (!matchesSearch) return false

      const s = head.verificationStatus?.toUpperCase() ?? 'PENDING'
      switch (activeFilter) {
        case 'PENDING':
          return s === 'PENDING'
        case 'VERIFIED':
          return s === 'VERIFIED'
        case 'MORE_INFO':
          return s === 'MOREINFORMATIONREQUIRED' || s === 'MORE_INFORMATION_REQUIRED'
        case 'REJECTED':
          return s === 'REJECTED'
        case 'SUSPENDED':
          return s === 'SUSPENDED'
        default:
          return true
      }
    })
  }, [familyHeads, search, activeFilter])

  const pendingCount = familyHeads.filter((h) => (h.verificationStatus?.toUpperCase() ?? 'PENDING') === 'PENDING').length
  const verifiedCount = familyHeads.filter((h) => h.verificationStatus?.toUpperCase() === 'VERIFIED').length

  return (
    <div className="page-stack">
      <header className="page-header">
        <div>
          <p className="eyebrow">Clinic administration</p>
          <h1>Family head verification</h1>
          <p>Manual administrative verification of family heads; no external registration API is claimed.</p>
        </div>
      </header>

      {message && <p role="status" className="status-banner">{message}</p>}

      {generatedTokenInfo && (
        <div className="panel" style={{ borderLeft: '4px solid var(--primary)', backgroundColor: 'rgba(16, 185, 129, 0.08)', marginBottom: '16px' }}>
          <h3>🔑 One-Time Reset Token Generated</h3>
          <p>
            Secure reset token for <strong>{generatedTokenInfo.email}</strong>:{' '}
            <strong style={{ fontFamily: 'monospace', fontSize: '1.1rem', color: 'var(--primary)', letterSpacing: '1px' }}>
              {generatedTokenInfo.token}
            </strong>
          </p>
          <p className="muted" style={{ fontSize: '0.85rem' }}>
            This token is valid for 30 minutes and has been logged to the audit trail.
          </p>
          <button type="button" className="button button--secondary button--sm" onClick={() => setGeneratedTokenInfo(null)}>
            Dismiss
          </button>
        </div>
      )}

      <section className="panel">
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '12px', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>
          <div style={{ display: 'flex', gap: '6px', flexWrap: 'wrap' }}>
            <button
              type="button"
              className={`button button--sm ${activeFilter === 'ALL' ? 'button--primary' : 'button--secondary'}`}
              onClick={() => setActiveFilter('ALL')}
            >
              All ({familyHeads.length})
            </button>
            <button
              type="button"
              className={`button button--sm ${activeFilter === 'PENDING' ? 'button--primary' : 'button--secondary'}`}
              onClick={() => setActiveFilter('PENDING')}
            >
              Pending ({pendingCount})
            </button>
            <button
              type="button"
              className={`button button--sm ${activeFilter === 'VERIFIED' ? 'button--primary' : 'button--secondary'}`}
              onClick={() => setActiveFilter('VERIFIED')}
            >
              Verified ({verifiedCount})
            </button>
            <button
              type="button"
              className={`button button--sm ${activeFilter === 'MORE_INFO' ? 'button--primary' : 'button--secondary'}`}
              onClick={() => setActiveFilter('MORE_INFO')}
            >
              More info
            </button>
            <button
              type="button"
              className={`button button--sm ${activeFilter === 'SUSPENDED' ? 'button--primary' : 'button--secondary'}`}
              onClick={() => setActiveFilter('SUSPENDED')}
            >
              Suspended
            </button>
            <button
              type="button"
              className={`button button--sm ${activeFilter === 'REJECTED' ? 'button--primary' : 'button--secondary'}`}
              onClick={() => setActiveFilter('REJECTED')}
            >
              Rejected
            </button>
          </div>

          <div style={{ minWidth: '260px' }}>
            <input
              type="search"
              placeholder="Search by ID, name, NIC, or email…"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              style={{ width: '100%', padding: '6px 12px', fontSize: '0.85rem' }}
            />
          </div>
        </div>

        {status === 'loading' ? (
          <LoadingState label="Loading family heads queue" />
        ) : status === 'error' ? (
          <ErrorState message="Family heads queue could not be loaded." onRetry={() => void load()} />
        ) : filteredHeads.length === 0 ? (
          <EmptyState
            title={search || activeFilter !== 'ALL' ? 'No matching family heads' : 'No family heads registered'}
            message={search || activeFilter !== 'ALL' ? 'Try changing your search query or status filter.' : 'New family head registrations appear here for manual review.'}
          />
        ) : (
          <div className="table-scroll">
            <table>
              <thead>
                <tr>
                  <th>Family ID</th>
                  <th>Family head</th>
                  <th>NIC</th>
                  <th>Address</th>
                  <th>Members</th>
                  <th>Status</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {filteredHeads.map((head) => {
                  const s = head.verificationStatus?.toUpperCase()
                  const isVerified = s === 'VERIFIED'
                  const isSuspendedOrRejected = s === 'SUSPENDED' || s === 'REJECTED'

                  return (
                    <tr key={head.userId}>
                      <td>
                        {head.familyCode ? (
                          <strong style={{ color: 'var(--primary)', fontFamily: 'monospace', fontSize: '0.95rem' }}>
                            {head.familyCode}
                          </strong>
                        ) : (
                          <span className="muted" style={{ fontStyle: 'italic', fontSize: '0.85rem' }}>
                            Pending
                          </span>
                        )}
                      </td>
                      <td>
                        <div>
                          <strong>{head.displayName}</strong>
                          <div className="muted" style={{ fontSize: '0.82rem' }}>{head.email}</div>
                        </div>
                      </td>
                      <td>
                        {head.nic ? (
                          <span style={{ fontFamily: 'monospace', fontSize: '0.85rem' }}>{head.nic}</span>
                        ) : (
                          <span className="muted">—</span>
                        )}
                      </td>
                      <td>
                        <div style={{ maxWidth: '200px', fontSize: '0.85rem', wordBreak: 'break-word' }}>
                          {head.address ?? <span className="muted">—</span>}
                        </div>
                      </td>
                      <td>{head.memberCount}</td>
                      <td>
                        <StatusBadge status={head.verificationStatus} />
                      </td>
                      <td>
                        <div className="table-actions">
                          {!isVerified && (
                            <button
                              className="button button--primary button--sm"
                              onClick={() => void decide(head.userId, 'verify')}
                              title="Verify and generate Family ID"
                            >
                              Verify
                            </button>
                          )}
                          {!isSuspendedOrRejected && (
                            <button
                              className="button button--secondary button--sm"
                              onClick={() => void decide(head.userId, 'request-info')}
                              title="Request additional information"
                            >
                              Request info
                            </button>
                          )}
                          {!isSuspendedOrRejected && (
                            <button
                              className="button button--danger button--sm"
                              onClick={() => void decide(head.userId, 'reject')}
                              title="Reject registration"
                            >
                              Reject
                            </button>
                          )}
                          {!isSuspendedOrRejected ? (
                            <button
                              className="button button--secondary button--sm"
                              onClick={() => void decide(head.userId, 'suspend')}
                              title="Suspend account access"
                            >
                              Suspend
                            </button>
                          ) : (
                            <button
                              className="button button--primary button--sm"
                              onClick={() => void decide(head.userId, 'verify')}
                              title="Reactivate and verify account"
                            >
                              Reactivate
                            </button>
                          )}
                          <button
                            className="button button--secondary button--sm"
                            onClick={() => void handleResetPassword(head.userId, head.email)}
                            title="Generate one-time password reset token"
                          >
                            Reset Password
                          </button>
                        </div>
                      </td>
                    </tr>
                  )
                })}
              </tbody>
            </table>
          </div>
        )}
      </section>
    </div>
  )
}
